python3 -c "import os, re, textwrap, pathlib, sys; target = pathlib.Path(os.environ['TARGET_DIR']) / 'run_buggy.py'; src = target.read_text(); pattern = re.compile(r'vectordb\s*=\s*Chroma\.from_documents\s*\((?:.|\n)*?\)', re.MULTILINE); m = pattern.search(src); 
if not m: sys.exit('Chroma.from_documents call not found'); old = m.group(0); 
new = textwrap.dedent('''
    # ENHANCED_PROGRAM_V1: Store per‑document metadata for source‑filtered retrieval
    metadata_list = [
        {
            "source": pdf_file.filename,
            "user": str(user_id),
            "created_at": now.strftime("%d/%m/%Y %H:%M:%S")
        }
        for _ in documents
    ]
    vectordb = Chroma.from_documents(
        documents,
        embedding=OpenAIEmbeddings(openai_api_key=config["OPENAI_API_KEY"], model=configs.EMBEDDINGS_MODEL),
        persist_directory='./trained_db',
        collection_name=collection.name,
        client=client,
        ids=ids,
        metadata=metadata_list,
    )
'''); 
new_src = src.replace(old, new); target.write_text(new_src); print('run_buggy.py updated')"

